const j = pm.response.json();
pm.test("200 OK", () => pm.response.to.have.status(200));
pm.test("returns a numeric id", () => pm.expect(j.id).to.be.a("number").and.above(0));
pm.test("new character is active, not deleted", () => { pm.expect(j.status).to.eql("active"); pm.expect(j.is_deleted).to.not.eql(true); });
pm.collectionVariables.set("charTestId", j.id);
pm.test("5A-1: picture_status is drawing", () => pm.expect(pm.response.json().picture_status).to.eql("drawing"));
pm.test("5A-1: created_at is a number", () => pm.expect(pm.response.json().created_at).to.be.a("number"));
pm.test("5A-1: no internal fields", () => { const j = pm.response.json(); ["users_id","data_models_id","primary_attributes"].forEach(k => pm.expect(j).to.not.have.property(k)); });

